http {
    gzip on;
    gzip_comp_level 6;
    gzip_vary on;
    gzip_proxied any;
    gzip_min_length 1024;
    gzip_buffers 16 8k;
    gzip_http_version 1.1;

    # Hanya kompres file teks — gambar & video sudah terkompresi
    gzip_types
        text/plain
        text/css
        text/javascript
        application/javascript
        application/json
        application/xml
        image/svg+xml;
}

# Kompresi semua aset statis saat deploy (level 9, sekali saja)
find /var/www/contoh.com/static -type f \( -name '*.js' -o -name '*.css' -o -name '*.html' -o -name '*.svg' \) -exec gzip -9 -k -f {} \;

# NGINX menyajikan file .gz bila tersedia
server {
    location /static/ {
        gzip_static on;
        gzip on;
        expires 30d;
        add_header Cache-Control 'public, immutable';
    }
}

http {
    # Brotli dulu (lebih kecil), gzip sebagai fallback
    brotli on;
    brotli_comp_level 6;
    brotli_types
        text/plain
        text/css
        text/javascript
        application/javascript
        application/json
        application/xml
        image/svg+xml;

    gzip on;
    gzip_comp_level 6;
    gzip_vary on;
    gzip_types
        text/plain
        text/css
        text/javascript
        application/javascript
        application/json;
}
